  if (refResponse.ok) {
    const refData = await refResponse.json();
    return refData.object?.sha ?? null;
  }

  if (refResponse.status === 404) {
    const mainRefUrl = `https://api.github.com/repos/${owner}/${repo}/git/ref/heads/main`;
