      params.blueprintName || '',
      params.blueprintContent || ''
    );
  }

  return { compilation, useDeterministicFallback };
}

function parseCompilationJson(str: string): CompilationOutput {
  let repaired = '';
  let inString = false;
  let escape = false;
  const stack: ('{' | '[')[] = [];

  for (let i = 0; i < str.length; i++) {
    const char = str[i];

    if (escape) {
      repaired += char;
      escape = false;
      continue;
    }

    if (char === '\\') {
      repaired += char;
      if (inString) escape = true;
      continue;
    }

    if (char === '"') {
      inString = !inString;
      repaired += char;
      continue;
    }

    if (inString) {
      if (char === '\n') repaired += '\\n';
      else if (char === '\r') repaired += '\\r';
      else repaired += char;
    } else {
      repaired += char;
      if (char === '{' || char === '[') {
        stack.push(char);
      } else if (char === '}') {
        if (stack[stack.length - 1] === '{') stack.pop();
      } else if (char === ']') {
        if (stack[stack.length - 1] === '[') stack.pop();
      }
    }
  }

  if (inString) repaired += '"';
  repaired = repaired.trimEnd();

  if (repaired.endsWith(',')) {
    repaired = repaired.slice(0, -1).trimEnd();
  } else if (repaired.endsWith(':')) {
    repaired += ' ""';
  }

  while (stack.length > 0) {
    const last = stack.pop();
    repaired += last === '{' ? '}' : ']';
  }

  return JSON.parse(repaired) as CompilationOutput;
}

