const EXTENSIONS_TO_INCLUDE = new Set(['.ts', '.tsx', '.js', '.jsx', '.css', '.json', '.html', '.prisma']);
const EXCLUDE_DIRS = new Set(['node_modules', '.next', '.git', 'download', 'work', 'upload', '.darleK-backups']);
